CREATE FUNCTION public.generate_transaction_code() RETURNS text
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN 'TRX-' || TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDD') || '-' || LPAD(nextval('transactions_id_seq')::TEXT, 6, '0');
END;
$$;


